import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

// Claude Code's own session transcript for this workspace. Nothing here is ours
// except the printing: the tool calls are what the agent actually did, in order.
const dir = path.join(os.homedir(), '.claude', 'projects', '-private-tmp-iauteur-rec-askills-bench');
const files = fs.existsSync(dir)
  ? fs.readdirSync(dir).filter(f => f.endsWith('.jsonl')).map(f => path.join(dir, f))
  : [];
// FAIL LOUDLY. An empty read-out looks exactly like "the agent used no tools", and a
// transcript is silently absent whenever CLAUDE_CODE_CHILD_SESSION is inherited.
if (!files.length) {
  console.error('NO TRANSCRIPT in ' + dir +
    ' — run the agent with CLAUDE_CODE_FORCE_SESSION_PERSISTENCE=1');
  process.exit(1);
}
const newest = files.sort((a, b) => fs.statSync(b).mtimeMs - fs.statSync(a).mtimeMs)[0];

let n = 0;
for (const line of fs.readFileSync(newest, 'utf8').split('\n')) {
  if (!line.trim()) continue;
  let d; try { d = JSON.parse(line); } catch { continue; }
  const c = d.message?.content;
  if (!Array.isArray(c)) continue;
  for (const b of c) {
    if (b.type !== 'tool_use') continue;
    n++;
    const i = b.input || {};
    const what = b.name === 'Skill' ? i.skill
      : (b.name === 'Edit' || b.name === 'Write') ? path.basename(i.file_path || '')
      : String(i.command || '').split('\n')[0].slice(0, 44);
    console.log(String(n).padStart(2) + '. ' + b.name.padEnd(6) + ' ' + what);
  }
}
if (!n) { console.error('TRANSCRIPT HAS NO TOOL CALLS — that is not a result, that is a bug'); process.exit(1); }
